/**
 * Per-codepoint cell location in the vanilla MC 1.21.4 font atlases.
 * Codepoint -> { atlas: 'ascii'|'accented'|'nonlatin_european', col, row }
 *
 * Each atlas has its own cell size + ascent (see ATLAS_META below) — the
 * editor uses both to crop the right pixels and align baselines across atlases.
 *
 * Generated alongside CHAR_ADVANCES — do not edit by hand.
 *   cd tools/minecraft-assets && bun gen-char-advances.ts [version]
 */

export type AtlasName = 'ascii' | 'accented' | 'nonlatin_european';

export interface AtlasMeta {
  /** Cell width in source pixels. All vanilla atlases are 16 cols wide. */
  cellW: number;
  /** Cell height in source pixels. */
  cellH: number;
  /** Vanilla ascent — distance from cell top to baseline. */
  ascent: number;
}

export const ATLAS_META: Readonly<Record<AtlasName, AtlasMeta>> = {
  ascii: { cellW: 8, cellH: 8, ascent: 7 },
  accented: { cellW: 9, cellH: 12, ascent: 10 },
  nonlatin_european: { cellW: 8, cellH: 8, ascent: 7 },
};

