const UNPACK: Readonly<Record<'a' | 'b' | 'n', AtlasName>> = {
  a: 'ascii', b: 'accented', n: 'nonlatin_european',
};

export interface CharCell {
  atlas: AtlasName;
  col: number;
  row: number;
}

/** Look up the atlas + cell for a single char. Returns null if unsupported. */
export function charCell(ch: string): CharCell | null {
  const cp = ch.codePointAt(0);
  if (cp === undefined) return null;
  const p = CELLS[cp];
  if (!p) return null;
  return { atlas: UNPACK[p[0]], col: p[1], row: p[2] };
}
